import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ContactoService, Contacto } from '../contacto.service';
import { ClienteService } from '../../cliente/cliente.service';

@Component({
  selector: 'app-contacto-detail',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './contacto-detail.component.html',
  styleUrls: ['./contacto-detail.component.css'],
})
export class ContactoDetailComponent implements OnInit {
  form: FormGroup;
  loading = false;
  submitted = false;
  error = '';
  isEditing = false;
  contactoId: number | null = null;
  clientes: any[] = [];

  constructor(
    private formBuilder: FormBuilder,
    private contactoService: ContactoService,
    private clienteService: ClienteService,
    private route: ActivatedRoute,
    private router: Router,
  ) {
    this.form = this.formBuilder.group({
      id_cliente: ['', Validators.required],
      nombre_contacto: ['', Validators.required],
      puesto_contacto: [''],
      telefono: [''],
      celular: [''],
      correo_electronico: ['', Validators.email],
      estado: [1],
    });
  }

  ngOnInit() {
    this.cargarClientes();
    this.route.params.subscribe((params) => {
      if (params['id']) {
        this.contactoId = +params['id'];
        this.isEditing = true;
        this.cargarContacto(this.contactoId!);
      }
    });
  }

  cargarClientes() {
    this.clienteService.listar().subscribe({
      next: (data) => (this.clientes = data),
    });
  }

  cargarContacto(id: number) {
    this.loading = true;
    this.contactoService.obtenerPorId(id).subscribe({
      next: (contacto) => {
        this.form.patchValue(contacto);
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar contacto';
        this.loading = false;
      },
    });
  }

  get f() {
    return this.form.controls;
  }

  onSubmit() {
    this.submitted = true;
    this.error = '';

    if (this.form.invalid) return;

    this.loading = true;
    const contacto = this.form.value;

    if (this.isEditing && this.contactoId) {
      this.contactoService.actualizar(this.contactoId, contacto).subscribe({
        next: () => this.router.navigate(['/contactos']),
        error: () => {
          this.error = 'Error al actualizar contacto';
          this.loading = false;
        },
      });
    } else {
      this.contactoService.crear(contacto).subscribe({
        next: () => this.router.navigate(['/contactos']),
        error: () => {
          this.error = 'Error al crear contacto';
          this.loading = false;
        },
      });
    }
  }

  cancelar() {
    this.router.navigate(['/contactos']);
  }
}
<div class="container">
  <div class="header">
    <h2>{{ isEditing ? 'Editar Contacto' : 'Nuevo Contacto' }}</h2>
  </div>

  <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
  <div *ngIf="loading && isEditing" class="loading">Cargando contacto...</div>

  <form [formGroup]="form" (ngSubmit)="onSubmit()" *ngIf="!loading || !isEditing" class="form">
    <div class="form-group">
      <label for="id_cliente">Cliente</label>
      <select id="id_cliente" formControlName="id_cliente" class="form-control"
        [class.is-invalid]="submitted && f['id_cliente'].errors">
        <option value="">Seleccionar cliente</option>
        <option *ngFor="let c of clientes" [value]="c.id_cliente">{{ c.nombre_comercial }}</option>
      </select>
      <div *ngIf="submitted && f['id_cliente'].errors" class="invalid-feedback">
        Cliente requerido
      </div>
    </div>

    <div class="form-group">
      <label for="nombre_contacto">Nombre</label>
      <input type="text" id="nombre_contacto" formControlName="nombre_contacto" class="form-control"
        [class.is-invalid]="submitted && f['nombre_contacto'].errors" />
      <div *ngIf="submitted && f['nombre_contacto'].errors" class="invalid-feedback">
        Nombre requerido
      </div>
    </div>

    <div class="form-group">
      <label for="puesto_contacto">Puesto</label>
      <input type="text" id="puesto_contacto" formControlName="puesto_contacto" class="form-control" />
    </div>

    <div class="form-group">
      <label for="telefono">Teléfono</label>
      <input type="text" id="telefono" formControlName="telefono" class="form-control" />
    </div>

    <div class="form-group">
      <label for="celular">Celular</label>
      <input type="text" id="celular" formControlName="celular" class="form-control" />
    </div>

    <div class="form-group">
      <label for="correo_electronico">Correo</label>
      <input type="email" id="correo_electronico" formControlName="correo_electronico" class="form-control"
        [class.is-invalid]="submitted && f['correo_electronico'].errors" />
      <div *ngIf="submitted && f['correo_electronico'].errors" class="invalid-feedback">
        <div *ngIf="f['correo_electronico'].errors['email']">Correo inválido</div>
      </div>
    </div>

    <div class="form-group">
      <label for="estado">Estado</label>
      <select id="estado" formControlName="estado" class="form-control">
        <option value="1">Activo</option>
        <option value="0">Inactivo</option>
      </select>
    </div>

    <div class="form-actions">
      <button type="submit" class="btn btn-primary" [disabled]="loading">
        {{ isEditing ? 'Actualizar' : 'Crear' }}
      </button>
      <button type="button" class="btn btn-secondary" (click)="cancelar()">Cancelar</button>
    </div>
  </form>
</div>
